arguments.query:
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?iri ?title ?status WHERE {
  ?iri rdf:type <https://moosedev.dev/kg/Requirement> ;
       rdfs:label ?title .
  OPTIONAL { ?iri <https://moosedev.dev/kg/hasLifecycleStatus> ?status }
}
ORDER BY LCASE(STR(?title))

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?iri ?title ?status WHERE {
  ?iri rdf:type <https://moosedev.dev/kg/Requirement> ;
       rdfs:label ?title .
  OPTIONAL { ?iri <https://moosedev.dev/kg/hasLifecycleStatus> ?status }
}
ORDER BY LCASE(STR(?title))

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT ?iri ?type ?title WHERE {
  ?iri <https://moosedev.dev/kg/hasTitle> ?title .
  OPTIONAL { ?iri rdf:type ?type }
}
ORDER BY ?type LCASE(STR(?title))

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT ?iri ?type ?title WHERE {
  ?iri <https://moosedev.dev/kg/hasTitle> ?title .
  OPTIONAL { ?iri rdf:type ?type }
}
ORDER BY ?type LCASE(STR(?title))

item.command:
/bin/zsh -lc "awk '
BEGIN{req=\"<https://trivyn.io/ontologies/software/architecture/domain/Requirement>\"}
"'$0 ~ /rdf-syntax-ns#type/ && $0 ~ req { sub(/''^</, "", $1); sub(/>$/, "", $1); isreq[$1]=1 }
$0 ~ /hasTitle/ { subj=$1; sub(/''^</, "", subj); sub(/>$/, "", subj); if (isreq[subj]) { match($0, /'"\\\"(["'^'"\\\"]+)\\\"/, m); if (m[1] "'!= "") title[subj]=m[1] } }
END { for (s in title) print title[s] }
'"' /tmp/codegraph_project.nt | sort"

